package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const Version = "v1.13.0"

func main() {
	if len(os.Args) > 1 {
		if os.Args[1] == "--help" || os.Args[1] == "-h" {
			printHelp()
			os.Exit(0)
		}
		if os.Args[1] == "--version" || os.Args[1] == "-v" {
			fmt.Println(Version)
			os.Exit(0)
		}
	}

	// Check for TTY
	if !hasTTY() {
		fmt.Println("Error: walk requires a terminal")
		os.Exit(1)
	}

	// Parse flags
	flags := parseFlags(os.Args[1:])

	// Get initial path
	path := "."
	if len(os.Args) > 2 {
		path = os.Args[2]
	}

	// Initialize app
	app := NewApp(flags, path)
	app.Run()
}

func hasTTY() bool {
	f, err := os.OpenFile("/dev/tty", os.O_RDONLY, 0)
	if err != nil {
		return false
	}
	f.Close()
	return true
}

func parseFlags(args []string) Flags {
	flags := Flags{}
	for _, arg := range args {
		switch arg {
		case "--icons":
			flags.icons = true
		case "--dir-only":
			flags.dirOnly = true
		case "--hide-hidden":
			flags.hideHidden = true
		case "--preview":
			flags.preview = true
		case "--with-border":
			flags.withBorder = true
		case "--fuzzy":
			flags.fuzzy = true
		}
	}
	return flags
}

type Flags struct {
	icons       bool
	dirOnly     bool
	hideHidden  bool
	preview     bool
	withBorder  bool
	fuzzy       bool
}

func printHelp() {
	fmt.Println(`
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y, copy       Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`)
}
