func (a *App) updateList() {
	a.files, _ = a.listFiles(a.path)
	a.selected = 0
}

func (a *App) runEventLoop() {
	// Read input from TTY
	reader := bufio.NewReader(a.tty)

	for {
		// Check for Ctrl+C
		if a.checkInterrupt() {
			break
		}

		// Read key
		key, _, err := reader.ReadRune()
		if err != nil {
			break
		}

		// Handle key
		a.handleKey(key)
	}
}

func (a *App) checkInterrupt() bool {
	// Check if terminal received SIGINT
	return false
}

func (a *App) handleKey(key rune) {
	switch key {
	case '\x1b': // Escape
		a.exitWithCD()
	case 'q':
		a.exitWithCD()
	case '\r': // Enter
		a.enterDirectory()
	case '\x7f': // Backspace
		a.goUp()
	case ' ':
		a.togglePreview()
	case '/':
		a.startSearch()
	case 'd':
		a.deleteFile()
	case 'u':
		a.undoDelete()
	case 'y':
		a.yank()
	case '.':
		a.toggleHidden()
	case '?':
		a.showHelp()
	case 'h', 'j', 'k', 'l':
		a.handleHJKL(key)
	case '\x03': // Ctrl+C
		os.Exit(0)
	}
}

func (a *App) handleHJKL(key rune) {
	switch key {
	case 'h':
		a.moveLeft()
	case 'j':
		a.moveDown()
	case 'k':
		a.moveUp()
	case 'l':
		a.moveRight()
	}
}

func (a *App) moveUp() {
	if a.selected > 0 {
		a.selected--
		a.updateList()
	}
}

func (a *App) moveDown() {
	if a.selected < len(a.files)-1 {
		a.selected++
		a.updateList()
	}
}

func (a *App) moveLeft() {
	if a.selected > 0 {
		a.selected = 0
		a.updateList()
	}
}

func (a *App) moveRight() {
	if a.selected < len(a.files)-1 {
		a.selected = len(a.files) - 1
		a.updateList()
	}
}

func (a *App) enterDirectory() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		newPath := filepath.Join(a.path, file)

		if info, err := os.Stat(newPath); err == nil && info.IsDir() {
			a.path = newPath
			a.files = []string{}
			a.selected = 0
			a.loadFiles()
		}
	}
}

func (a *App) goUp() {
	parent := filepath.Dir(a.path)
	if parent != a.path {
		a.path = parent
		a.files = []string{}
		a.selected = 0
		a.loadFiles()
	}
}

func (a *App) exitWithCD() {
	// Change to selected directory
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		newPath := filepath.Join(a.path, file)

		if info, err := os.Stat(newPath); err == nil && info.IsDir() {
			os.Chdir(newPath)
		}
	}

	// Exit
	os.Exit(0)
}
