const Version = "v1.13.0"

type App struct {
	*App
	*App
}

func main() {
	if len(os.Args) > 1 {
		if os.Args[1] == "--help" || os.Args[1] == "-h" {
			printHelp()
			os.Exit(0)
		}
		if os.Args[1] == "--version" || os.Args[1] == "-v" {
			fmt.Println(Version)
			os.Exit(0)
		}
	}

	// Check for TTY
	if !hasTTY() {
		fmt.Println("Error: walk requires a terminal")
		os.Exit(1)
	}

	// Parse flags
	flags := parseFlags(os.Args[1:])

	// Get initial path
	path := "."
	if len(os.Args) > 2 {
		path = os.Args[2]
	}

	// Initialize app
	app := NewApp(flags, path)
	app.Run()
}

func hasTTY() bool {
	f, err := os.OpenFile("/dev/tty", os.O_RDONLY, 0)
	if err != nil {
		return false
	}
	f.Close()
	return true
}

func parseFlags(args []string) Flags {
	flags := Flags{}
	for _, arg := range args {
		switch arg {
		case "--icons":
			flags.icons = true
		case "--dir-only":
			flags.dirOnly = true
		case "--hide-hidden":
			flags.hideHidden = true
		case "--preview":
			flags.preview = true
		case "--with-border":
			flags.withBorder = true
		case "--fuzzy":
			flags.fuzzy = true
		}
	}
	return flags
}

type Flags struct {
	icons       bool
	dirOnly     bool
	hideHidden  bool
	preview     bool
	withBorder  bool
	fuzzy       bool
}

func printHelp() {
	fmt.Println(`
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y, copy       Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`)
}

func NewApp(flags Flags, path string) *App {
	app := &App{
		flags: flags,
		path:  path,
	}
	return app
}

type App struct {
	flags Flags
	path  string

	// UI components
	list       *tview.List
	preview    *tview.TextView
	statusBar  *tview.TextView
	inputField *tview.InputField

	// State
	files      []string
	selected   int
	previewOn  bool
	searchMode bool
	searchText string

	// Clipboard
	clipboard string

	// Undo stack
	undoStack []string

	// TTY
	tty *os.File

	// Status bar expression
	statusBarExpr string
}

func (a *App) Run() {
	// Setup TTY
	a.setupTTY()

	// Load status bar expression
	a.loadStatusBarExpr()

	// Create UI
	a.createUI()

	// Load files
	a.loadFiles()

	// Start event loop
	a.app.SetInputCapture(a.handleInput)
	a.app.SetFocus(a.inputField)

	// Run app
	a.app.Run()
}

func (a *App) setupTTY() {
	// Open TTY
	var err error
	a.tty, err = os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: could not open a new TTY: %v\n", err)
		os.Exit(1)
	}
}

func (a *App) loadStatusBarExpr() {
	a.statusBarExpr = os.Getenv("WALK_STATUS_BAR")
}

func (a *App) createUI() {
	a.app = tview.NewApplication()

	// Create list
	a.list = tview.NewList().
		SetBorder(true).
		SetTitle("Files").
		SetTitleAlign(tview.AlignLeft)

	// Create preview
	a.preview = tview.NewTextView().
		SetDynamicColors(true).
		SetBorder(true).
		SetTitle("Preview").
		SetTitleAlign(tview.AlignLeft)

	// Create status bar
	a.statusBar = tview.NewTextView().
		SetDynamicColors(true).
		SetTitle("Status").
		SetTitleAlign(tview.AlignLeft)

	// Create input field
	a.inputField = tview.NewInputField().
		SetFieldWidth(1)

	// Layout
	flex := tview.NewFlex().
		SetDirection(tview.FlexRow).
		AddItem(a.list, 0, 1, true).
		AddItem(a.preview, 0, 1, false).
		AddItem(a.statusBar, 1, 0, false)

	a.app.SetRoot(flex, true)
}

func (a *App) loadFiles() {
	files, err := a.listFiles(a.path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	a.files = files
	a.selected = 0
	a.updateList()
}

func (a *App) listFiles(path string) ([]string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}

	var files []string
	for _, entry := range entries {
		if a.shouldHide(entry) {
			continue
		}
		files = append(files, entry.Name())
	}

	return files, nil
}

func (a *App) shouldHide(entry os.DirEntry) bool {
	if a.flags.dirOnly {
		return !entry.IsDir()
	}
	if a.flags.hideHidden {
		return strings.HasPrefix(entry.Name(), ".")
	}
	return false
}

func (a *App) updateList() {
	a.list.Clear()

	for i, file := range a.files {
		info, err := os.Stat(filepath.Join(a.path, file))
		if err != nil {
			continue
		}

		icon := ""
		if a.flags.icons {
			icon = a.getIcon(info)
		}

		text := icon + file
		a.list.AddItem(text, "", 1, i)
	}
}

func (a *App) getIcon(info os.FileInfo) string {
	if info.IsDir() {
		return "📁 "
	}
	return ""
}

func (a *App) handleInput(event *tcell.EventKey) *tcell.EventKey {
	switch event.Key() {
	case tcell.KeyUp:
		a.moveUp()
	case tcell.KeyDown:
		a.moveDown()
	case tcell.KeyRight:
		a.moveRight()
	case tcell.KeyLeft:
		a.moveLeft()
	case tcell.KeyEnter:
		a.enterDirectory()
	case tcell.KeyBackspace2:
		a.goUp()
	case tcell.KeyEscape:
		a.exitWithCD()
	case tcell.KeyRune:
		switch event.Rune() {
		case 'q':
			a.exitWithCD()
		case ' ':
			a.togglePreview()
		case '/':
			a.startSearch()
		case 'd':
			a.deleteFile()
		case 'u':
			a.undoDelete()
		case 'y':
			a.yank()
		case '.':
			a.toggleHidden()
		case '?':
			a.showHelp()
		}
	}
	return event
}

func (a *App) moveUp() {
	if a.selected > 0 {
		a.selected--
		a.updateList()
		a.updateStatusBar()
	}
}

func (a *App) moveDown() {
	if a.selected < len(a.files)-1 {
		a.selected++
		a.updateList()
		a.updateStatusBar()
	}
}

func (a *App) moveRight() {
	if a.selected < len(a.files)-1 {
		a.selected = len(a.files) - 1
		a.updateList()
		a.updateStatusBar()
	}
}

func (a *App) moveLeft() {
	if a.selected > 0 {
		a.selected = 0
		a.updateList()
		a.updateStatusBar()
	}
}

func (a *App) enterDirectory() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		newPath := filepath.Join(a.path, file)

		if info, err := os.Stat(newPath); err == nil && info.IsDir() {
			a.path = newPath
			a.files = []string{}
			a.selected = 0
			a.loadFiles()
			a.updateStatusBar()
		}
	}
}

func (a *App) goUp() {
	parent := filepath.Dir(a.path)
	if parent != a.path {
		a.path = parent
		a.files = []string{}
		a.selected = 0
		a.loadFiles()
		a.updateStatusBar()
	}
}

func (a *App) exitWithCD() {
	// Change to selected directory
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		newPath := filepath.Join(a.path, file)

		if info, err := os.Stat(newPath); err == nil && info.IsDir() {
			os.Chdir(newPath)
		}
	}

	// Exit
	os.Exit(0)
}

func (a *App) togglePreview() {
	a.previewOn = !a.previewOn
	if a.previewOn {
		a.preview.SetVisible(true)
	} else {
		a.preview.SetVisible(false)
	}
}

func (a *App) startSearch() {
	a.searchMode = true
	a.searchText = ""
	a.inputField.SetText("")
	a.inputField.SetFocus()
}

func (a *App) deleteFile() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		path := filepath.Join(a.path, file)

		if info, err := os.Stat(path); err == nil {
			if info.IsDir() {
				a.deleteDir(path)
			} else {
				a.deleteFile(path)
			}
		}
	}
}

func (a *App) deleteFile(path string) {
	os.Remove(path)
	a.undoStack = append(a.undoStack, path)
	a.loadFiles()
	a.updateStatusBar()
}

func (a *App) deleteDir(path string) {
	os.RemoveAll(path)
	a.undoStack = append(a.undoStack, path)
	a.loadFiles()
	a.updateStatusBar()
}

func (a *App) undoDelete() {
	if len(a.undoStack) > 0 {
		path := a.undoStack[len(a.undoStack)-1]
		a.undoStack = a.undoStack[:len(a.undoStack)-1]

		if info, err := os.Stat(path); err == nil && info.IsDir() {
			os.MkdirAll(path, 0755)
		} else {
			os.WriteFile(path, []byte{}, 0644)
		}
		a.loadFiles()
		a.updateStatusBar()
	}
}

func (a *App) yank() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		a.clipboard = file
	}
}

func (a *App) toggleHidden() {
	a.flags.hideHidden = !a.flags.hideHidden
	a.loadFiles()
	a.updateList()
	a.updateStatusBar()
}

func (a *App) showHelp() {
	a.preview.SetText(`
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y, copy       Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`)
}

func (a *App) updateStatusBar() {
	if a.statusBarExpr != "" {
		// Evaluate status bar expression
		result := a.evaluateStatusBar()
		a.statusBar.SetText(result)
	} else {
		a.statusBar.SetText("")
	}
}

func (a *App) evaluateStatusBar() string {
	// Simple implementation - just return empty for now
	return ""
}

func (a *App) Run() {
	// Run the app
	a.app.Run()
