	// Read input from TTY
	reader := bufio.NewReader(a.tty)

	for {
		// Check for Ctrl+C
		if a.checkInterrupt() {
			break
		}

		// Read key
		key, _, err := reader.ReadRune()
		if err != nil {
			break
		}

		// Handle key
		a.handleKey(key)
	}
