type App struct {
	flags Flags
	path  string

	files      []string
	selected   int
	previewOn  bool
	searchMode bool
	searchText string

	clipboard string
	undoStack []string

	tty *os.File
	statusBarExpr string
}

func NewApp(flags Flags, path string) *App {
	app := &App{
		flags: flags,
		path:  path,
	}
	return app
}

func (a *App) Run() {
	a.setupTTY()
	a.loadStatusBarExpr()
	a.loadFiles()
	a.runEventLoop()
}

func (a *App) setupTTY() {
	var err error
	a.tty, err = os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: could not open a new TTY: %v\n", err)
		os.Exit(1)
	}
}

func (a *App) loadStatusBarExpr() {
	a.statusBarExpr = os.Getenv("WALK_STATUS_BAR")
}

func (a *App) loadFiles() {
	files, err := a.listFiles(a.path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	a.files = files
	a.selected = 0
	a.updateList()
}

func (a *App) listFiles(path string) ([]string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}

	var files []string
	for _, entry := range entries {
		if a.shouldHide(entry) {
			continue
		}
		files = append(files, entry.Name())
	}

	return files, nil
}

func (a *App) shouldHide(entry os.DirEntry) bool {
	if a.flags.dirOnly {
		return !entry.IsDir()
	}
	if a.flags.hideHidden {
		return strings.HasPrefix(entry.Name(), ".")
	}
	return false
}

func (a *App) updateList() {
	a.files, _ = a.listFiles(a.path)
	a.selected = 0
}

func (a *App) runEventLoop() {
	reader := bufio.NewReader(a.tty)

	for {
		if a.checkInterrupt() {
			break
		}

		key, _, err := reader.ReadRune()
		if err != nil {
			break
		}

		a.handleKey(key)
	}
}

func (a *App) checkInterrupt() bool {
	return false
}

func (a *App) handleKey(key rune) {
	switch key {
	case '\x1b':
		a.exitWithCD()
	case 'q':
		a.exitWithCD()
	case '\r':
		a.enterDirectory()
	case '\x7f':
		a.goUp()
	case ' ':
		a.togglePreview()
	case '/':
		a.startSearch()
	case 'd':
		a.deleteFile()
	case 'u':
		a.undoDelete()
	case 'y':
		a.yank()
	case '.':
		a.toggleHidden()
	case '?':
		a.showHelp()
	case 'h', 'j', 'k', 'l':
		a.handleHJKL(key)
	case '\x03':
		os.Exit(0)
	}
}

func (a *App) handleHJKL(key rune) {
	switch key {
	case 'h':
		a.moveLeft()
	case 'j':
		a.moveDown()
	case 'k':
		a.moveUp()
	case 'l':
		a.moveRight()
	}
}

func (a *App) moveUp() {
	if a.selected > 0 {
		a.selected--
		a.updateList()
	}
}

func (a *App) moveDown() {
	if a.selected < len(a.files)-1 {
		a.selected++
		a.updateList()
	}
}

func (a *App) moveLeft() {
	if a.selected > 0 {
		a.selected = 0
		a.updateList()
	}
}

func (a *App) moveRight() {
	if a.selected < len(a.files)-1 {
		a.selected = len(a.files) - 1
		a.updateList()
	}
}

func (a *App) enterDirectory() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		newPath := filepath.Join(a.path, file)

		if info, err := os.Stat(newPath); err == nil && info.IsDir() {
			a.path = newPath
			a.files = []string{}
			a.selected = 0
			a.loadFiles()
		}
	}
}

func (a *App) goUp() {
	parent := filepath.Dir(a.path)
	if parent != a.path {
		a.path = parent
		a.files = []string{}
		a.selected = 0
		a.loadFiles()
	}
}

func (a *App) exitWithCD() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		newPath := filepath.Join(a.path, file)

		if info, err := os.Stat(newPath); err == nil && info.IsDir() {
			os.Chdir(newPath)
		}
	}

	os.Exit(0)
}

func (a *App) togglePreview() {
	a.previewOn = !a.previewOn
}

func (a *App) startSearch() {
	a.searchMode = true
	a.searchText = ""
}

func (a *App) deleteFile() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		path := filepath.Join(a.path, file)

		if info, err := os.Stat(path); err == nil {
			if info.IsDir() {
				a.deleteDir(path)
			} else {
				a.deleteFileInternal(path)
			}
		}
	}
}

func (a *App) deleteFileInternal(path string) {
	os.Remove(path)
	a.undoStack = append(a.undoStack, path)
	a.loadFiles()
}

func (a *App) deleteDir(path string) {
	os.RemoveAll(path)
	a.undoStack = append(a.undoStack, path)
	a.loadFiles()
}

func (a *App) undoDelete() {
	if len(a.undoStack) > 0 {
		path := a.undoStack[len(a.undoStack)-1]
		a.undoStack = a.undoStack[:len(a.undoStack)-1]

		if info, err := os.Stat(path); err == nil && info.IsDir() {
			os.MkdirAll(path, 0755)
		} else {
			os.WriteFile(path, []byte{}, 0644)
		}
		a.loadFiles()
	}
}

func (a *App) yank() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		a.clipboard = file
	}
}

func (a *App) toggleHidden() {
	a.flags.hideHidden = !a.flags.hideHidden
	a.loadFiles()
}

func (a *App) showHelp() {
	fmt.Println("\033]11;?\033\033[6n")
	fmt.Printf("  walk %s\r\n\r\n", Version)
	fmt.Println("  Usage: walk [path]\r\n")
	fmt.Println("    arrows, hjkl  Move cursor")
	fmt.Println("    enter         Enter directory")
	fmt.Println("    backspace     Exit directory")
