		fmt.Println("Error: walk requires a terminal")
		os.Exit(1)
	}

	// Parse flags
	flags := parseFlags(os.Args[1:])

	// Get initial path
	path := "."
	if len(os.Args) > 2 {
		path = os.Args[2]
	}

	// Initialize app
	app := NewApp(flags, path)
	app.Run()
}

func hasTTY() bool {
	f, err := os.OpenFile("/dev/tty", os.O_RDONLY, 0)
	if err != nil {
		return false
	}
	f.Close()
	return true
}

func parseFlags(args []string) Flags {
	flags := Flags{}
	for _, arg := range args {
		switch arg {
		case "--icons":
			flags.icons = true
		case "--dir-only":
			flags.dirOnly = true
		case "--hide-hidden":
			flags.hideHidden = true
		case "--preview":
			flags.preview = true
		case "--with-border":
			flags.withBorder = true
		case "--fuzzy":
			flags.fuzzy = true
		}
	}
	return flags
}

type Flags struct {
	icons       bool
	dirOnly     bool
	hideHidden  bool
	preview     bool
	withBorder  bool
	fuzzy       bool
}

func printHelp() {
	fmt.Print("\033]11;?\033\033[6n")
	fmt.Printf("  walk %s\r\n\r\n", Version)
	fmt.Println("  Usage: walk [path]\r\n")
	fmt.Println("    arrows, hjkl  Move cursor")
	fmt.Println("    enter         Enter directory")
	fmt.Println("    backspace     Exit directory")
	fmt.Println("    space         Toggle preview")
	fmt.Println("    esc, q        Exit with cd")
	fmt.Println("    ctrl+c        Exit without cd")
	fmt.Println("    /             Fuzzy search")
	fmt.Println("    d, delete     Delete file or dir")
	fmt.Println("    y             Copy to clipboard")
	fmt.Println("    .             Hide hidden files")
	fmt.Println("    ?             Show help")
	fmt.Println()
	fmt.Println("  Flags:\r\n")
	fmt.Println("    --icons        display icons")
	fmt.Println("    --dir-only     show dirs only")
	fmt.Println("    --hide-hidden  hide hidden files")
	fmt.Println("    --preview      display preview")
	fmt.Println("    --with-border  preview with border")
	fmt.Println("    --fuzzy        fuzzy mode")
	fmt.Println()
}

type App struct {
	flags Flags
	path  string

	// State
	files      []string
	selected   int
	previewOn  bool
	searchMode bool
	searchText string

	// Clipboard
	clipboard string

	// Undo stack
	undoStack []string

	// TTY
	tty *os.File

	// Status bar expression
	statusBarExpr string
}

func NewApp(flags Flags, path string) *App {
	app := &App{
		flags: flags,
		path:  path,
	}
	return app
}

func (a *App) Run() {
	// Setup TTY
	a.setupTTY()

	// Load status bar expression
	a.loadStatusBarExpr()

	// Load files
	a.loadFiles()

	// Start event loop
	a.runEventLoop()
}

func (a *App) setupTTY() {
	// Open TTY
	var err error
	a.tty, err = os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: could not open a new TTY: %v\n", err)
		os.Exit(1)
	}
}

func (a *App) loadStatusBarExpr() {
	a.statusBarExpr = os.Getenv("WALK_STATUS_BAR")
}

func (a *App) loadFiles() {
	files, err := a.listFiles(a.path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	a.files = files
	a.selected = 0
	a.updateList()
}

func (a *App) listFiles(path string) ([]string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}

	var files []string
	for _, entry := range entries {
		if a.shouldHide(entry) {
			continue
		}
		files = append(files, entry.Name())
	}

	return files, nil
}

func (a *App) shouldHide(entry os.DirEntry) bool {
	if a.flags.dirOnly {
		return !entry.IsDir()
	}
	if a.flags.hideHidden {
		return strings.HasPrefix(entry.Name(), ".")
	}
	return false
}

func (a *App) updateList() {
	a.files, _ = a.listFiles(a.path)
	a.selected = 0
}

func (a *App) runEventLoop() {
	// Read input from TTY
	reader := bufio.NewReader(a.tty)

	for {
		// Check for Ctrl+C
		if a.checkInterrupt() {
			break
		}

		// Read key
		key, _, err := reader.ReadRune()
		if err != nil {
			break
		}

		// Handle key
		a.handleKey(key)
	}
}

func (a *App) checkInterrupt() bool {
	// Check if terminal received SIGINT
	return false
}

func (a *App) handleKey(key rune) {
	switch key {
	case '\x1b': // Escape
		a.exitWithCD()
	case 'q':
		a.exitWithCD()
	case '\r': // Enter
		a.enterDirectory()
