		a.yank()
	case '.':
		a.toggleHidden()
	case '?':
		a.showHelp()
	case 'h', 'j', 'k', 'l':
		a.handleHJKL(key)
	case '\x03': // Ctrl+C
		os.Exit(0)
	}
}

func (a *App) handleHJKL(key rune) {
	switch key {
	case 'h':
		a.moveLeft()
	case 'j':
		a.moveDown()
	case 'k':
		a.moveUp()
	case 'l':
		a.moveRight()
	}
}

func (a *App) moveUp() {
	if a.selected > 0 {
		a.selected--
		a.updateList()
	}
}

func (a *App) moveDown() {
	if a.selected < len(a.files)-1 {
		a.selected++
		a.updateList()
	}
}

func (a *App) moveLeft() {
	if a.selected > 0 {
		a.selected = 0
		a.updateList()
	}
}

func (a *App) moveRight() {
	if a.selected < len(a.files)-1 {
		a.selected = len(a.files) - 1
		a.updateList()
	}
}

func (a *App) enterDirectory() {
	if a.selected >= 0 && a.selected < len(a.files) {
		file := a.files[a.selected]
		newPath := filepath.Join(a.path, file)

		if info, err := os.Stat(newPath); err == nil && info.IsDir() {
			a.path = newPath
			a.files = []string{}
			a.selected = 0
			a.loadFiles()
		}
	}
