++		key, _, err := reader.ReadRune()
++		if err != nil {
++			break
++		}
++		
++		// Handle key
++		a.handleKey(key)
++	}
++}
++
++func (a *App) checkInterrupt() bool {
++	// Check if terminal received SIGINT
++	return false
++}
++
++func (a *App) handleKey(key rune) {
++	switch key {
++	case '\x1b': // Escape
++		a.exitWithCD()
++	case 'q':
++		a.exitWithCD()
++	case '\r': // Enter
++		a.enterDirectory()
++	case '\x7f': // Backspace
++		a.goUp()
++	case ' ':
++		a.togglePreview()
++	case '/':
++		a.startSearch()
++	case 'd':
++		a.deleteFile()
++	case 'u':
++		a.undoDelete()
++	case 'y':
++		a.yank()
++	case '.':
++		a.toggleHidden()
++	case '?':
++		a.showHelp()
++	case 'h', 'j', 'k', 'l':
++		a.handleHJKL(key)
++	case '\x03': // Ctrl+C
++		os.Exit(0)
++	}
++}
++
++func (a *App) handleHJKL(key rune) {
++	switch key {
++	case 'h':
++		a.moveLeft()
++	case 'j':
++		a.moveDown()
++	case 'k':
++		a.moveUp()
++	case 'l':
++		a.moveRight()
++	}
++}
++
++func (a *App) moveUp() {
++	if a.selected > 0 {
++		a.selected--
++		a.updateList()
++	}
++}
++
++func (a *App) moveDown() {
++	if a.selected < len(a.files)-1 {
++		a.selected++
++		a.updateList()
++	}
++}
++
++func (a *App) moveLeft() {
++	if a.selected > 0 {
++		a.selected = 0
